    /**
     * getBankInfo
     *
     * @param  string $binInfoCode
     * @return array
     */
    public function getBankInfo($binInfoCode)
    {
        $bankId = substr($binInfoCode, 0, 3);
        $branchId = substr($binInfoCode, 3, 4);

        $bankInfo = $this->allBankInfo();

        $bankName = $bankInfo[$bankId][self::BANK_NAME] ?? '';
        $branchName = $bankInfo[$bankId][self::BRANCH_LIST][$branchId] ?? '';
        
        return [
            self::BANK_NAME => $bankName,
            self::BRANCH_NAME => $branchName
        ];
    }

    /**
     * allBankInfo
     *
     * @return array
     */
    public function allBankInfo()
    {
        $allBankInfo = json_decode(self::DATA, true);
        $returnArray = [];

        foreach ($allBankInfo as $value) {
            $returnArray[$value['id']] = [
                self::BANK_NAME => $value['name'],
                self::BRANCH_LIST => $this->branchList($value[self::BRANCH_LIST])
            ];
        }

        return $returnArray;
    }

    /**
     * branchList
     *
     * @param  mixed $branchList
     * @return array
     */
    public function branchList(array $branchList)
    {
        $returnArray = [];
        foreach ($branchList as $branch) {
            $returnArray[$branch[self::BRANCH_ID]] = $branch[self::BRANCH_NAME];
        }
        return $returnArray;
    }
    
    /**
     * getBankName
     *
     * @param  string $binInfoCode
     * @return string
     */
    public function getBankName($binInfoCode) 
    {
      $info = $this->getBankInfo($binInfoCode);

      return $info[self::BANK_NAME]. $info[self::BRANCH_NAME];
    }
}
